CREATE TABLE IF NOT EXISTS `partners` (`id` INTEGER NOT NULL, `workspaceId` TEXT NOT NULL, `name` TEXT NOT NULL, `phone` TEXT NOT NULL, `role` TEXT NOT NULL, `avatarColorHex` TEXT NOT NULL, `photoUri` TEXT NOT NULL, `isCurrentActive` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL, `firebaseUid` TEXT NOT NULL, PRIMARY KEY(`workspaceId`, `id`));
CREATE TABLE IF NOT EXISTS `tractors` (`id` INTEGER NOT NULL, `workspaceId` TEXT NOT NULL, `label` TEXT NOT NULL, `chassisNo` TEXT NOT NULL, `modelYear` TEXT NOT NULL, `operatorName` TEXT NOT NULL, `isActive` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL, `createdByUid` TEXT NOT NULL, PRIMARY KEY(`workspaceId`, `id`));
CREATE TABLE IF NOT EXISTS `customers` (`id` INTEGER NOT NULL, `workspaceId` TEXT NOT NULL, `name` TEXT NOT NULL, `phone` TEXT NOT NULL, `location` TEXT NOT NULL, `totalBilled` REAL NOT NULL, `totalPaid` REAL NOT NULL, `balanceDue` REAL NOT NULL, `isSynced` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, `createdByUid` TEXT NOT NULL, PRIMARY KEY(`workspaceId`, `id`));
CREATE TABLE IF NOT EXISTS `job_entries` (`id` INTEGER NOT NULL, `workspaceId` TEXT NOT NULL, `customerId` INTEGER NOT NULL, `customerName` TEXT NOT NULL, `customerPhone` TEXT NOT NULL, `customerLocation` TEXT NOT NULL, `operatorName` TEXT NOT NULL, `tractorId` INTEGER NOT NULL, `tractorLabel` TEXT NOT NULL, `workType` TEXT NOT NULL, `startTimeMillis` INTEGER NOT NULL, `endTimeMillis` INTEGER NOT NULL, `durationMinutes` INTEGER NOT NULL, `hourlyRate` REAL NOT NULL, `totalAmount` REAL NOT NULL, `amountReceived` REAL NOT NULL, `pendingAmount` REAL NOT NULL, `addedByPartner` TEXT NOT NULL, `notes` TEXT NOT NULL, `isSynced` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL, `createdByUid` TEXT NOT NULL, `createdByRole` TEXT NOT NULL, `editedByUid` TEXT NOT NULL, `editedByName` TEXT NOT NULL, `editedByRole` TEXT NOT NULL, `updatedAt` INTEGER NOT NULL, `isHistorical` INTEGER NOT NULL, `entryForUid` TEXT NOT NULL, `financialAttributionUid` TEXT NOT NULL, PRIMARY KEY(`workspaceId`, `id`));
CREATE TABLE IF NOT EXISTS `expenses` (`id` INTEGER NOT NULL, `workspaceId` TEXT NOT NULL, `expenseType` TEXT NOT NULL, `amount` REAL NOT NULL, `tractorId` INTEGER NOT NULL, `tractorLabel` TEXT NOT NULL, `operatorName` TEXT NOT NULL, `description` TEXT NOT NULL, `addedByPartner` TEXT NOT NULL, `dateTimestamp` INTEGER NOT NULL, `relatedJobId` INTEGER, `isSynced` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL, `paidBy` TEXT NOT NULL, `paidByPartner` TEXT NOT NULL, `paidByUid` TEXT NOT NULL, `createdByUid` TEXT NOT NULL, `createdByRole` TEXT NOT NULL, `expenseForUid` TEXT NOT NULL, `financialAttributionUid` TEXT NOT NULL, PRIMARY KEY(`workspaceId`, `id`));
CREATE TABLE IF NOT EXISTS `withdrawals` (`id` INTEGER NOT NULL, `workspaceId` TEXT NOT NULL, `partnerId` INTEGER NOT NULL, `partnerName` TEXT NOT NULL, `amount` REAL NOT NULL, `category` TEXT NOT NULL, `note` TEXT NOT NULL, `timestamp` INTEGER NOT NULL, `isSynced` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL, `targetPartnerUid` TEXT NOT NULL, `createdByUid` TEXT NOT NULL, `createdByRole` TEXT NOT NULL, PRIMARY KEY(`workspaceId`, `id`));
CREATE TABLE IF NOT EXISTS `app_settings` (`workspaceId` TEXT NOT NULL, `businessName` TEXT NOT NULL, `ownerName` TEXT NOT NULL, `businessPhone` TEXT NOT NULL, `businessAddress` TEXT NOT NULL, `gstNumber` TEXT NOT NULL, `defaultHourlyRate` REAL NOT NULL, `currency` TEXT NOT NULL, `language` TEXT NOT NULL, `sharedAccountId` TEXT NOT NULL, `isLoggedIn` INTEGER NOT NULL, `activePartnerName` TEXT NOT NULL, `activePartnerPhone` TEXT NOT NULL, `profilePhotoUri` TEXT NOT NULL, `lockedTractorLabel` TEXT NOT NULL, `lastSyncTime` INTEGER NOT NULL, PRIMARY KEY(`workspaceId`));
CREATE TABLE IF NOT EXISTS `payments` (`id` INTEGER NOT NULL, `workspaceId` TEXT NOT NULL, `jobEntryId` INTEGER NOT NULL, `customerId` INTEGER NOT NULL, `customerName` TEXT NOT NULL, `tractorId` INTEGER NOT NULL, `tractorLabel` TEXT NOT NULL, `amount` REAL NOT NULL, `paymentMethod` TEXT NOT NULL, `notes` TEXT NOT NULL, `collectedByUid` TEXT NOT NULL, `collectedByName` TEXT NOT NULL, `collectedByRole` TEXT NOT NULL, `collectedAt` INTEGER NOT NULL, `isSynced` INTEGER NOT NULL, `status` TEXT NOT NULL, `reversedAt` INTEGER NOT NULL, `reversedByUid` TEXT NOT NULL, `allocationsJson` TEXT NOT NULL, `createdAt` INTEGER NOT NULL, PRIMARY KEY(`workspaceId`, `id`));
CREATE TABLE IF NOT EXISTS `checklist_items` (`id` INTEGER NOT NULL, `workspaceId` TEXT NOT NULL, `text` TEXT NOT NULL, `isChecked` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL, PRIMARY KEY(`workspaceId`, `id`));
CREATE TABLE IF NOT EXISTS `work_type_extensions` (`id` INTEGER NOT NULL, `workspaceId` TEXT NOT NULL, `name` TEXT NOT NULL, `createdAt` INTEGER NOT NULL, `createdByUid` TEXT NOT NULL, PRIMARY KEY(`workspaceId`, `id`));
CREATE TABLE IF NOT EXISTS `pending_operations` (`operationId` TEXT NOT NULL, `workspaceId` TEXT NOT NULL, `actorUid` TEXT NOT NULL, `entityType` TEXT NOT NULL, `entityId` INTEGER NOT NULL, `mutationType` TEXT NOT NULL, `sequence` INTEGER NOT NULL, `actionTime` INTEGER NOT NULL, `payloadJson` TEXT NOT NULL, `state` TEXT NOT NULL, `attempts` INTEGER NOT NULL, `failureReason` TEXT NOT NULL, PRIMARY KEY(`operationId`));
CREATE INDEX IF NOT EXISTS `index_pending_operations_workspaceId_actorUid_sequence` ON `pending_operations` (`workspaceId`, `actorUid`, `sequence`);
CREATE TABLE IF NOT EXISTS `deleted_members` (`workspaceId` TEXT NOT NULL, `uid` TEXT NOT NULL, `displayName` TEXT NOT NULL, `role` TEXT NOT NULL, `removedAt` INTEGER NOT NULL, `removedByUid` TEXT NOT NULL, `purgeState` TEXT NOT NULL, `backupPath` TEXT NOT NULL, `backupSha256` TEXT NOT NULL, PRIMARY KEY(`workspaceId`, `uid`));